INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3d6d7152-589d-553b-8088-2119ece0ae0f', 'Austria''s National Energy and Climate Plan (NECP)', 'Austria''s National Energy and Climate Plan (NECP)', 'The Integrated National Energy and Climate Plan (NECP) for Austria outlines the country’s strategy to meet its climate and energy goals for 2021-2030. It focuses on achieving substantial decarbonization, improving energy efficiency, and ensuring security of energy supply. The NECP includes concrete targets like reducing greenhouse gas emissions by 36% compared to 2005 levels, increasing the share of renewable energy to 45-50% of gross final energy consumption, and achieving 100% renewable electricity by 2030.', 'The Integrated National Energy and Climate Plan (NECP) for Austria outlines the country’s strategy to meet its climate and energy goals for 2021-2030. It focuses on achieving substantial decarbonization, improving energy efficiency, and ensuring security of energy supply. The NECP includes concrete targets like reducing greenhouse gas emissions by 36% compared to 2005 levels, increasing the share of renewable energy to 45-50% of gross final energy consumption, and achieving 100% renewable electricity by 2030.', 'The Integrated National Energy and Climate Plan (NECP) for Austria outlines the country’s strategy to meet its climate and energy goals for 2021-2030. It focuses on achieving substantial decarbonization, improving energy efficiency, and ensuring security of energy supply. The NECP includes concrete targets like reducing greenhouse gas emissions by 36% compared to 2005 levels, increasing the share of renewable energy to 45-50% of gross final energy consumption, and achieving 100% renewable electricity by 2030.', 'Austria', 'climate', 'in_force', '2020-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_6', ARRAY['sdg13', 'sdg7', 'sdg17', 'mandatory', 'austria', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f2d60918-9c1f-5719-a88e-469ee433dd07', 'Austria Rules Prime Market', 'Rules Prime Market', 'This document is concerned with the rules of the prime market, a market segment of the Vienna Stock Exchange on which stocks are listed of companies that have signed agreements with the exchange regarding obligations that go beyond the legal admission criteria for the Official Market of the Vienna Stock Exchange.', 'This document is concerned with the rules of the prime market, a market segment of the Vienna Stock Exchange on which stocks are listed of companies that have signed agreements with the exchange regarding obligations that go beyond the legal admission criteria for the Official Market of the Vienna Stock Exchange.', 'This document is concerned with the rules of the prime market, a market segment of the Vienna Stock Exchange on which stocks are listed of companies that have signed agreements with the exchange regarding obligations that go beyond the legal admission criteria for the Official Market of the Vienna Stock Exchange.', 'Austria', 'governance', 'in_force', '2019-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_3', ARRAY['mandatory', 'mandatory_regulations', 'austria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3b1318a2-65f8-5af6-ac2b-ea39396ca979', 'Austria 20. Federal law amending the Corporate Code, the', '20. Federal law amending the Corporate Code, the Stock Corporation Act and the GmbH Act to improve sustainability and diversity reporting (Sustainability and Diversity Improvement Act, NaDiVeG)', 'This document is concerned with the Federal law amending the Corporate Code, the Stock Corporation Act and the GmbH Act to improve sustainability and diversity reporting (Sustainability and Diversity Improvement Act, NaDiVeG).', 'This document is concerned with the Federal law amending the Corporate Code, the Stock Corporation Act and the GmbH Act to improve sustainability and diversity reporting (Sustainability and Diversity Improvement Act, NaDiVeG).', 'This document is concerned with the Federal law amending the Corporate Code, the Stock Corporation Act and the GmbH Act to improve sustainability and diversity reporting (Sustainability and Diversity Improvement Act, NaDiVeG).', 'Austria', 'climate', 'in_force', '2017-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_22', ARRAY['sdg13', 'regulations', 'mandatory', 'austria', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d574e98e-df0c-585a-b6bc-c94307b029f6', 'Austria Federal Constitutional Law on Sustainability, Animal Welfare, Comprehensive', 'Federal Constitutional Law on Sustainability, Animal Welfare, Comprehensive Environmental Protection, Ensuring Water and Food Supply and Research', 'Austria''s 2013 Federal Constitutional Law emphasizes sustainability, animal welfare, environmental protection, water and food supply, and research. It commits to sustainable resource use, animal welfare, comprehensive environmental protection, water supply, food quality, and research importance, managed by the federal government to ensure future generations'' well-being.', 'Austria''s 2013 Federal Constitutional Law emphasizes sustainability, animal welfare, environmental protection, water and food supply, and research. It commits to sustainable resource use, animal welfare, comprehensive environmental protection, water supply, food quality, and research importance, managed by the federal government to ensure future generations'' well-being.', 'Austria''s 2013 Federal Constitutional Law emphasizes sustainability, animal welfare, environmental protection, water and food supply, and research. It commits to sustainable resource use, animal welfare, comprehensive environmental protection, water supply, food quality, and research importance, managed by the federal government to ensure future generations'' well-being.', 'Austria', 'climate', 'in_force', '2013-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_30', ARRAY['sdg14', 'regulations', 'mandatory', 'sdg6', 'austria', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b5e24a34-81d3-52e6-b496-b75efbe73dae', 'Austrian Code of Corporate Governance July', 'Austrian Code of Corporate Governance July 2012', 'The focus of the 2012 revision of Austrian Code of Corporate Governance is on the development of the diversity rule and the inclusion of new rules to improve cooperation between supervisory board and auditors.', 'The focus of the 2012 revision of Austrian Code of Corporate Governance is on the development of the diversity rule and the inclusion of new rules to improve cooperation between supervisory board and auditors.', 'The focus of the 2012 revision of Austrian Code of Corporate Governance is on the development of the diversity rule and the inclusion of new rules to improve cooperation between supervisory board and auditors.', 'Austria', 'social', 'in_force', '2012-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_11', ARRAY['sdg10', 'sdg17', 'mandatory', 'austria', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d6dc8b47-823a-50c8-b2cb-d6629e53588e', 'Austria Federal law on a system for trading', 'Federal law on a system for trading in greenhouse gas emission certificates (Emission Certificates Act 2011 – EZG 2011)', 'The aim of this federal law is to create a system for trading in greenhouse gas emission certificates in order to reduce greenhouse gas emissions in a cost-effective and economically efficient manner.', 'The aim of this federal law is to create a system for trading in greenhouse gas emission certificates in order to reduce greenhouse gas emissions in a cost-effective and economically efficient manner.', 'The aim of this federal law is to create a system for trading in greenhouse gas emission certificates in order to reduce greenhouse gas emissions in a cost-effective and economically efficient manner.', 'Austria', 'climate', 'in_force', '2011-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_16', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'austria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('36e0915c-17e7-5c3b-b5ea-d958e3605836', 'Austrian Pollutant Release and Transfer Register (PRTR)', 'Austrian Pollutant Release and Transfer Register (PRTR)', 'The Republic of Austria signed the UNECE Pollutant Release and Transfer Register on 21 May 2003 and ratified it on 23 March 2010.', 'The Republic of Austria signed the UNECE Pollutant Release and Transfer Register on 21 May 2003 and ratified it on 23 March 2010.', 'The Republic of Austria signed the UNECE Pollutant Release and Transfer Register on 21 May 2003 and ratified it on 23 March 2010.', 'Austria', 'governance', 'in_force', '2010-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_14', ARRAY['mandatory', 'mandatory_regulations', 'austria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e13d6a1-6879-5c74-b959-a8d3f5b562cf', 'Austria Success and Social Responsibility - A Guide', 'Success and Social Responsibility - A Guide to Future-Proofing Your Business', '"Success and Social Responsibility - A Guide to Future-Proofing Your Business" aims to provide Austrian companies with practical advice on how to integrate social responsibility into their business practices and strategies. It covers a range of topics, including ethical behavior, environmental sustainability, stakeholder engagement, and social commitment. The guide emphasizes the importance of a long-term perspective and a comprehensive approach to social responsibility, and provides case studies and examples of companies that have successfully implemented social responsibility initiatives. Overall, the guide encourages Austrian businesses to see social responsibility not as a burden, but as an opportunity for innovation, growth, and competitive advantage.', '"Success and Social Responsibility - A Guide to Future-Proofing Your Business" aims to provide Austrian companies with practical advice on how to integrate social responsibility into their business practices and strategies. It covers a range of topics, including ethical behavior, environmental sustainability, stakeholder engagement, and social commitment. The guide emphasizes the importance of a long-term perspective and a comprehensive approach to social responsibility, and provides case studies and examples of companies that have successfully implemented social responsibility initiatives. Overall, the guide encourages Austrian businesses to see social responsibility not as a burden, but as an opportunity for innovation, growth, and competitive advantage.', '"Success and Social Responsibility - A Guide to Future-Proofing Your Business" aims to provide Austrian companies with practical advice on how to integrate social responsibility into their business practices and strategies. It covers a range of topics, including ethical behavior, environmental sustainability, stakeholder engagement, and social commitment. The guide emphasizes the importance of a long-term perspective and a comprehensive approach to social responsibility, and provides case studies and examples of companies that have successfully implemented social responsibility initiatives. Overall, the guide encourages Austrian businesses to see social responsibility not as a burden, but as an opportunity for innovation, growth, and competitive advantage.', 'Austria', 'climate', 'in_force', '2010-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_21', ARRAY['other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'austria', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
