INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f4c580f-35de-570f-8ab9-5668a412a07c', 'Austrian Code of Corporate Governance January', 'Austrian Code of Corporate Governance January 2006', 'This Code of Corporate Governance gives listed companies a set of voluntarily rules to help them establish good corporate governance and control systems. The revised Code as amended in January 2006 will continue to be decisive for building confidence in the Austrian capital market.', 'This Code of Corporate Governance gives listed companies a set of voluntarily rules to help them establish good corporate governance and control systems. The revised Code as amended in January 2006 will continue to be decisive for building confidence in the Austrian capital market.', 'This Code of Corporate Governance gives listed companies a set of voluntarily rules to help them establish good corporate governance and control systems. The revised Code as amended in January 2006 will continue to be decisive for building confidence in the Austrian capital market.', 'Austria', 'governance', 'in_force', '2006-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_7', ARRAY['mandatory', 'austria', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e35c486-d485-53e0-91be-d7c56c2cac80', 'Austrian Code of Corporate Governance February', 'Austrian Code of Corporate Governance February 2005', 'The Code aims to establish a system of management and control of companies and groups that is accountable and is geared to creating sustainable, long-term value. Its objective is to serve the needs of all parties whose well-being depends on the success of the enterprise.', 'The Code aims to establish a system of management and control of companies and groups that is accountable and is geared to creating sustainable, long-term value. Its objective is to serve the needs of all parties whose well-being depends on the success of the enterprise.', 'The Code aims to establish a system of management and control of companies and groups that is accountable and is geared to creating sustainable, long-term value. Its objective is to serve the needs of all parties whose well-being depends on the success of the enterprise.', 'Austria', 'governance', 'in_force', '2005-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_9', ARRAY['mandatory', 'austria', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0b9cabc-5003-5fa2-aa5d-547cd772f2f5', 'Austria Federal Law on Sustainable Waste Management (Waste Management', 'Federal Law on Sustainable Waste Management (Waste Management Act 2002 – AWG 2002)', 'The "Bundesgesetz über eine nachhaltige Abfallwirtschaft (Abfallwirtschaftsgesetz 2002 – AWG 2002)" is an Austrian federal law that was passed in 2002. The law aims to promote sustainable waste management in Austria by establishing a legal framework for the collection, transport, treatment, and disposal of waste. The law sets out specific obligations for waste producers, waste collectors, and waste treatment facilities, including requirements related to waste prevention, reuse, and recycling. The law also includes provisions on the monitoring and enforcement of waste management activities, as well as on the responsibilities of federal, state, and local authorities in the management of waste. Overall, the AWG 2002 reflects Austria''s commitment to environmental sustainability and the promotion of a circular economy.Bottom of Form', 'The "Bundesgesetz über eine nachhaltige Abfallwirtschaft (Abfallwirtschaftsgesetz 2002 – AWG 2002)" is an Austrian federal law that was passed in 2002. The law aims to promote sustainable waste management in Austria by establishing a legal framework for the collection, transport, treatment, and disposal of waste. The law sets out specific obligations for waste producers, waste collectors, and waste treatment facilities, including requirements related to waste prevention, reuse, and recycling. The law also includes provisions on the monitoring and enforcement of waste management activities, as well as on the responsibilities of federal, state, and local authorities in the management of waste. Overall, the AWG 2002 reflects Austria''s commitment to environmental sustainability and the promotion of a circular economy.Bottom of Form', 'The "Bundesgesetz über eine nachhaltige Abfallwirtschaft (Abfallwirtschaftsgesetz 2002 – AWG 2002)" is an Austrian federal law that was passed in 2002. The law aims to promote sustainable waste management in Austria by establishing a legal framework for the collection, transport, treatment, and disposal of waste. The law sets out specific obligations for waste producers, waste collectors, and waste treatment facilities, including requirements related to waste prevention, reuse, and recycling. The law also includes provisions on the monitoring and enforcement of waste management activities, as well as on the responsibilities of federal, state, and local authorities in the management of waste. Overall, the AWG 2002 reflects Austria''s commitment to environmental sustainability and the promotion of a circular economy.Bottom of Form', 'Austria', 'climate', 'in_force', '2002-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_23', ARRAY['regulations', 'sdg11', 'mandatory', 'austria', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('09061dce-d175-59a4-87af-c9dd59836767', 'Austria Federal law on the assessment of environmental compatibility', 'Federal law on the assessment of environmental compatibility (Environmental Impact Assessment Act 2000 - UVP-G 2000)', 'This document contains the federal law on the assessment of environmental compatibility (Environmental Impact Assessment Act 2000 - UVP-G 2000).', 'This document contains the federal law on the assessment of environmental compatibility (Environmental Impact Assessment Act 2000 - UVP-G 2000).', 'This document contains the federal law on the assessment of environmental compatibility (Environmental Impact Assessment Act 2000 - UVP-G 2000).', 'Austria', 'climate', 'in_force', '2000-01-01'::date, 'Austria', 'https://www.carrotsandsticks.org/policies/9_17', ARRAY['sdg13', 'regulations', 'sdg7', 'sdg11', 'sdg9', 'mandatory', 'sdg6', 'austria', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8e600b92-d136-507e-a654-7b37d741c263', 'Azerbaijan About Environmental Impact Assessment', 'About Environmental Impact Assessment', 'In accordance with Article 39 of the Constitution of the Republic of Azerbaijan and Clause 20 of Part I of Article 94 of the Constitution of the Republic of Azerbaijan, this Law establishes the legal, economic and organizational basis and regulates the relations arising in this field.', 'In accordance with Article 39 of the Constitution of the Republic of Azerbaijan and Clause 20 of Part I of Article 94 of the Constitution of the Republic of Azerbaijan, this Law establishes the legal, economic and organizational basis and regulates the relations arising in this field.', 'In accordance with Article 39 of the Constitution of the Republic of Azerbaijan and Clause 20 of Part I of Article 94 of the Constitution of the Republic of Azerbaijan, this Law establishes the legal, economic and organizational basis and regulates the relations arising in this field.', 'Azerbaijan', 'climate', 'in_force', '2018-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_13', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'sdg9', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
