INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d2ea8c9e-4ffa-51e7-8424-dc1b00c7ff0c', 'Azerbaijan About Ecologically Clean Agriculture', 'About Ecologically Clean Agriculture', 'This Law regulates the relations related to the production, processing, and circulation of ecologically clean agricultural and food products in the Republic of Azerbaijan, ensuring the health and safety of the population, soil, water, plants and animals.', 'This Law regulates the relations related to the production, processing, and circulation of ecologically clean agricultural and food products in the Republic of Azerbaijan, ensuring the health and safety of the population, soil, water, plants and animals.', 'This Law regulates the relations related to the production, processing, and circulation of ecologically clean agricultural and food products in the Republic of Azerbaijan, ensuring the health and safety of the population, soil, water, plants and animals.', 'Azerbaijan', 'nature', 'in_force', '2008-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_16', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'sdg15', 'sdg3', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('11f2d28e-d567-5522-8456-a68f21ec155e', 'Azerbaijan "Rules of inventory of wastes generated in the', 'On the Approval of the "Rules of inventory of wastes generated in the production process"', 'This Regulation was prepared in order to ensure the implementation of clause 1.3 of the Decree of the President of the Republic of Azerbaijan dated July 31, 2007 No. 609 "On the implementation of the Law of the Republic of Azerbaijan "On Amendments and Additions to the Law of the Republic of Azerbaijan "On Production and Household Waste" and determines the procedure for inventorying the waste generated in the process.', 'This Regulation was prepared in order to ensure the implementation of clause 1.3 of the Decree of the President of the Republic of Azerbaijan dated July 31, 2007 No. 609 "On the implementation of the Law of the Republic of Azerbaijan "On Amendments and Additions to the Law of the Republic of Azerbaijan "On Production and Household Waste" and determines the procedure for inventorying the waste generated in the process.', 'This Regulation was prepared in order to ensure the implementation of clause 1.3 of the Decree of the President of the Republic of Azerbaijan dated July 31, 2007 No. 609 "On the implementation of the Law of the Republic of Azerbaijan "On Amendments and Additions to the Law of the Republic of Azerbaijan "On Production and Household Waste" and determines the procedure for inventorying the waste generated in the process.', 'Azerbaijan', 'circularity', 'in_force', '2008-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_3', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'sdg9', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a65ce55f-265c-5105-858e-071fe8a02cf8', 'Azerbaijan Decision on Radiation Safety of the Population', 'Decision on Radiation Safety of the Population', 'These Rules are based on the Presidential Decree of 1998 On the application of the Law of the Republic of Azerbaijan on radiation safety of the population.', 'These Rules are based on the Presidential Decree of 1998 On the application of the Law of the Republic of Azerbaijan on radiation safety of the population.', 'These Rules are based on the Presidential Decree of 1998 On the application of the Law of the Republic of Azerbaijan on radiation safety of the population.', 'Azerbaijan', 'climate', 'in_force', '2004-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_7', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ee8a1b7-00c6-522d-84b2-591c5087fe49', 'Azerbaijan Amount of payments for Rules of state registration', 'Amount of payments for Rules of state registration of harmful substances and harmful physical effects on the atmosphere […]', 'These Rules were developed in connection with the implementation of the Decree of the President of the Republic of Azerbaijan No. 501 of June 11, 2001 "On the application of the Law of the Republic of Azerbaijan" On protection of atmospheric air "and determine the rules of state registration of harmful substances and physical effects. The main purpose of the state registration of harmful effects on the atmosphere is to obtain information on the objects that have a harmful effect, the amount and composition of harmful substances released into the atmosphere, as well as the types and scale of harmful physical effects on the atmosphere.', 'These Rules were developed in connection with the implementation of the Decree of the President of the Republic of Azerbaijan No. 501 of June 11, 2001 "On the application of the Law of the Republic of Azerbaijan" On protection of atmospheric air "and determine the rules of state registration of harmful substances and physical effects. The main purpose of the state registration of harmful effects on the atmosphere is to obtain information on the objects that have a harmful effect, the amount and composition of harmful substances released into the atmosphere, as well as the types and scale of harmful physical effects on the atmosphere.', 'These Rules were developed in connection with the implementation of the Decree of the President of the Republic of Azerbaijan No. 501 of June 11, 2001 "On the application of the Law of the Republic of Azerbaijan" On protection of atmospheric air "and determine the rules of state registration of harmful substances and physical effects. The main purpose of the state registration of harmful effects on the atmosphere is to obtain information on the objects that have a harmful effect, the amount and composition of harmful substances released into the atmosphere, as well as the types and scale of harmful physical effects on the atmosphere.', 'Azerbaijan', 'climate', 'in_force', '2002-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_6', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg9', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('427c7cdd-f50b-56b3-8cf8-ba5ce6221484', 'Law of the Azerbaijan Republic on Protection', 'Law of the Azerbaijan Republic on Protection of Atmospheric Air', 'Atmospheric air is the integral component of the environment influencing health, work capacity of people, flora and fauna. The present law, establishing legal bases for protection of atmospheric air, is directed on realization of the rights of population to live in favorable environment and to receive correct information on the environment.', 'Atmospheric air is the integral component of the environment influencing health, work capacity of people, flora and fauna. The present law, establishing legal bases for protection of atmospheric air, is directed on realization of the rights of population to live in favorable environment and to receive correct information on the environment.', 'Atmospheric air is the integral component of the environment influencing health, work capacity of people, flora and fauna. The present law, establishing legal bases for protection of atmospheric air, is directed on realization of the rights of population to live in favorable environment and to receive correct information on the environment.', 'Azerbaijan', 'climate', 'in_force', '2001-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_12', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'sdg9', 'sdg3', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('530685a3-deee-53f0-b554-9bfaa7de6856', 'Azerbaijan Rules of Transportation of Dangerous Goods by Rail', 'On the Approval of the Rules of Transportation of Dangerous Goods by Rail', 'These Rules determine the requirements for ensuring safety in the carriage of dangerous goods by rail in the territory of the Republic of Azerbaijan in accordance with the Law of the Republic of Azerbaijan "On Transport".', 'These Rules determine the requirements for ensuring safety in the carriage of dangerous goods by rail in the territory of the Republic of Azerbaijan in accordance with the Law of the Republic of Azerbaijan "On Transport".', 'These Rules determine the requirements for ensuring safety in the carriage of dangerous goods by rail in the territory of the Republic of Azerbaijan in accordance with the Law of the Republic of Azerbaijan "On Transport".', 'Azerbaijan', 'climate', 'in_force', '2000-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_2', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg9', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('57411232-f4e8-5004-b5b0-a52e213e3362', 'Azerbaijan Rules of Transportation of Dangerous Cargoes by Air', 'On the Approval of the Rules of Transportation of Dangerous Cargoes by Air', 'These Rules determine the special conditions for the carriage of dangerous goods by air and are the main normative and legal document that must be complied with by organizations, legal entities and individuals involved in the carriage of such cargo by air.', 'These Rules determine the special conditions for the carriage of dangerous goods by air and are the main normative and legal document that must be complied with by organizations, legal entities and individuals involved in the carriage of such cargo by air.', 'These Rules determine the special conditions for the carriage of dangerous goods by air and are the main normative and legal document that must be complied with by organizations, legal entities and individuals involved in the carriage of such cargo by air.', 'Azerbaijan', 'climate', 'in_force', '2000-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_4', ARRAY['other sustainability policy', 'sdg11', 'mandatory', 'mandatory_regulations', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73032fbf-94a7-5976-8613-c40f64215087', 'Azerbaijan Rules of Transportation of Dangerous Goods by Sea', 'On the Approval of the Rules of Transportation of Dangerous Goods by Sea', 'These Rules determine the relevant requirements for ensuring safety in the carriage of dangerous goods by sea in the territory of the Republic of Azerbaijan in accordance with the Law of the Republic of Azerbaijan "On Transport".', 'These Rules determine the relevant requirements for ensuring safety in the carriage of dangerous goods by sea in the territory of the Republic of Azerbaijan in accordance with the Law of the Republic of Azerbaijan "On Transport".', 'These Rules determine the relevant requirements for ensuring safety in the carriage of dangerous goods by sea in the territory of the Republic of Azerbaijan in accordance with the Law of the Republic of Azerbaijan "On Transport".', 'Azerbaijan', 'climate', 'in_force', '2000-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_5', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4797301b-74c8-5be4-b38f-83b4d87aa419', 'Civil Code of the Azerbaijani Republic', 'The Civil Code of the Azerbaijani Republic, 1999', 'The purpose of this Code is to secure the freedom of civil relationships based upon the equality of the parties without prejudice to affecting the rights of other persons.', 'The purpose of this Code is to secure the freedom of civil relationships based upon the equality of the parties without prejudice to affecting the rights of other persons.', 'The purpose of this Code is to secure the freedom of civil relationships based upon the equality of the parties without prejudice to affecting the rights of other persons.', 'Azerbaijan', 'governance', 'in_force', '1999-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_10', ARRAY['mandatory', 'other sustainability policy', 'mandatory_regulations', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d1831ec-7d45-5c75-b0a0-48b969a82b02', 'Azerbaijan Labour code', 'The Labour code of the Republic of Azerbaijan, 1999', 'The Labor Code of the Republic of Azerbaijan shall govern labor relations between employees and employers, as well as other legal relations derived from such relations between them and relevant national authorities and entities but shall also establish the minimum norms for regulations ensuring implementation of the labor rights of physical persons and these rights themselves.', 'The Labor Code of the Republic of Azerbaijan shall govern labor relations between employees and employers, as well as other legal relations derived from such relations between them and relevant national authorities and entities but shall also establish the minimum norms for regulations ensuring implementation of the labor rights of physical persons and these rights themselves.', 'The Labor Code of the Republic of Azerbaijan shall govern labor relations between employees and employers, as well as other legal relations derived from such relations between them and relevant national authorities and entities but shall also establish the minimum norms for regulations ensuring implementation of the labor rights of physical persons and these rights themselves.', 'Azerbaijan', 'social', 'in_force', '1999-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_11', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5b064dca-ae27-5edd-acdb-8f74d0e1b0fc', 'Azerbaijan About Environmental Protection', 'About Environmental Protection', 'This Law determines the legal, economic and social bases of environmental protection. The purpose of the law is to ensure environmental safety in the field of protection of the ecological balance of the environment, prevention of harmful effects of economic and other activities on natural ecosystems, conservation of biological diversity and effective organization of the use of medicine. Additionally, this Law regulates the interaction of nature and society in order to improve the quality of the environment, the efficient use and restoration of natural resources, and the strengthening of legislation and regulations in the field of environmental protection.', 'This Law determines the legal, economic and social bases of environmental protection. The purpose of the law is to ensure environmental safety in the field of protection of the ecological balance of the environment, prevention of harmful effects of economic and other activities on natural ecosystems, conservation of biological diversity and effective organization of the use of medicine. Additionally, this Law regulates the interaction of nature and society in order to improve the quality of the environment, the efficient use and restoration of natural resources, and the strengthening of legislation and regulations in the field of environmental protection.', 'This Law determines the legal, economic and social bases of environmental protection. The purpose of the law is to ensure environmental safety in the field of protection of the ecological balance of the environment, prevention of harmful effects of economic and other activities on natural ecosystems, conservation of biological diversity and effective organization of the use of medicine. Additionally, this Law regulates the interaction of nature and society in order to improve the quality of the environment, the efficient use and restoration of natural resources, and the strengthening of legislation and regulations in the field of environmental protection.', 'Azerbaijan', 'climate', 'in_force', '1999-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_17', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'sdg15', 'sdg3', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f54f02e2-5a56-5205-b5a2-ef83bf6868a9', 'Law of the Azerbaijan Republic on Water Supply', 'The Law of the Azerbaijan Republic on Water Supply and Sewage', 'The purpose of the present Law consists in regulation of relations in the area of maintenance of the population, enterprises, establishments and organizations by qualitative water meeting the requirements of state standards in necessary quantity, discharge sewage.', 'The purpose of the present Law consists in regulation of relations in the area of maintenance of the population, enterprises, establishments and organizations by qualitative water meeting the requirements of state standards in necessary quantity, discharge sewage.', 'The purpose of the present Law consists in regulation of relations in the area of maintenance of the population, enterprises, establishments and organizations by qualitative water meeting the requirements of state standards in necessary quantity, discharge sewage.', 'Azerbaijan', 'governance', 'in_force', '1999-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_18', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d6409c7f-6cfb-52e6-9a11-9800f0d4939d', 'Law of Azerbaijani Republic on Industrial and Domestic Waste', 'The Law of Azerbaijani Republic on Industrial and Domestic Waste', 'The present Law establishes the state policy in the area of environment protection from industrial and domestic waste (hereinafter– waste) formed in the Azerbaijan Republic as a result of human activity in the form of substances and things, decrease of danger of influence of the given waste, maintenance of ecological balance in the nature, use of waste as secondary raw material, regulates the relations connected to waste, except for harmful gases, polluted waters and radioactive waste.', 'The present Law establishes the state policy in the area of environment protection from industrial and domestic waste (hereinafter– waste) formed in the Azerbaijan Republic as a result of human activity in the form of substances and things, decrease of danger of influence of the given waste, maintenance of ecological balance in the nature, use of waste as secondary raw material, regulates the relations connected to waste, except for harmful gases, polluted waters and radioactive waste.', 'The present Law establishes the state policy in the area of environment protection from industrial and domestic waste (hereinafter– waste) formed in the Azerbaijan Republic as a result of human activity in the form of substances and things, decrease of danger of influence of the given waste, maintenance of ecological balance in the nature, use of waste as secondary raw material, regulates the relations connected to waste, except for harmful gases, polluted waters and radioactive waste.', 'Azerbaijan', 'nature', 'in_force', '1998-01-01'::date, 'Azerbaijan', 'https://www.carrotsandsticks.org/policies/10_15', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg9', 'mandatory', 'sdg6', 'sdg12', 'sdg15', 'azerbaijan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06cfdbe3-eac6-50a7-bf8b-e2c3b39a15ac', 'Bahrain Environmental, Social and Governance (ESG) Reporting Guidelines', 'Environmental, Social and Governance (ESG) Reporting Guidelines, 2023', 'The objective of this ESG Reporting Guidelines is to establish a uniform framework for listed companies and licensees to disclose their ESG performance and sustainability efforts.', 'The objective of this ESG Reporting Guidelines is to establish a uniform framework for listed companies and licensees to disclose their ESG performance and sustainability efforts.', 'The objective of this ESG Reporting Guidelines is to establish a uniform framework for listed companies and licensees to disclose their ESG performance and sustainability efforts.', 'Bahrain', 'climate', 'in_force', '2023-01-01'::date, 'Bahrain', 'https://www.carrotsandsticks.org/policies/12_5', ARRAY['guidance_frameworks', 'sdg7', 'sdg16', 'disclosure', 'sdg9', 'voluntary', 'bahrain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('495e3be7-5645-5083-a361-2e2238051f49', 'Bahrain ESG Reporting Guide. Supporting sustainable capital markets through', 'ESG Reporting Guide. Supporting sustainable capital markets through enhanced disclosure, 2022', 'This ESG reporting guidance aims to increase awareness and understanding of the importance and benefits of ESG reporting and disclosure by establishing a roadmap for companies on integrating ESG into business decisions, company strategy, reporting, and operations. This guide aims to assist listed companies to address environmental, social and governance (ESG) issues in their reporting to meet the requirements of institutional investors for material ESG information.', 'This ESG reporting guidance aims to increase awareness and understanding of the importance and benefits of ESG reporting and disclosure by establishing a roadmap for companies on integrating ESG into business decisions, company strategy, reporting, and operations. This guide aims to assist listed companies to address environmental, social and governance (ESG) issues in their reporting to meet the requirements of institutional investors for material ESG information.', 'This ESG reporting guidance aims to increase awareness and understanding of the importance and benefits of ESG reporting and disclosure by establishing a roadmap for companies on integrating ESG into business decisions, company strategy, reporting, and operations. This guide aims to assist listed companies to address environmental, social and governance (ESG) issues in their reporting to meet the requirements of institutional investors for material ESG information.', 'Bahrain', 'climate', 'in_force', '2022-01-01'::date, 'Bahrain', 'https://www.carrotsandsticks.org/policies/12_4', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9', 'bahrain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bcc2dcef-f71e-58a3-bc93-deca83460d5e', 'Bahrain Bourse ESG Reporting Guide', 'Bahrain Bourse ESG Reporting Guide, 2020', 'This ESG reporting guidance is an important new tool that aims to encourage and assist listed issuers in providing ESG information that investors use to inform their investment decisions while also supporting companies align with Bahrain Economic Vision 2030 and the UN Sustainable Development Goals (SDGs).', 'This ESG reporting guidance is an important new tool that aims to encourage and assist listed issuers in providing ESG information that investors use to inform their investment decisions while also supporting companies align with Bahrain Economic Vision 2030 and the UN Sustainable Development Goals (SDGs).', 'This ESG reporting guidance is an important new tool that aims to encourage and assist listed issuers in providing ESG information that investors use to inform their investment decisions while also supporting companies align with Bahrain Economic Vision 2030 and the UN Sustainable Development Goals (SDGs).', 'Bahrain', 'climate', 'in_force', '2020-01-01'::date, 'Bahrain', 'https://www.carrotsandsticks.org/policies/12_1', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'bahrain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('72e74863-315d-53ac-81f8-1c2ca70fd78b', 'Bahrain Corporate Governance Code', 'Corporate Governance Code, 2018', 'The Code aims to provide guidance to companies on the best ways to manage, lead, organize and monitor their businesses through a series of transparent, clearly defined policies, processes and procedures.', 'The Code aims to provide guidance to companies on the best ways to manage, lead, organize and monitor their businesses through a series of transparent, clearly defined policies, processes and procedures.', 'The Code aims to provide guidance to companies on the best ways to manage, lead, organize and monitor their businesses through a series of transparent, clearly defined policies, processes and procedures.', 'Bahrain', 'governance', 'in_force', '2018-01-01'::date, 'Bahrain', 'https://www.carrotsandsticks.org/policies/12_2', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'disclosure', 'sdg9', 'bahrain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e0715cab-dd3d-55d9-af8a-c19dc0d79af4', 'Bahrain Corporate Governance Code', 'Corporate Governance Code, 2010', 'The purpose of this Code is to establish best-practice corporate governance principles in Bahrain, and to provide protection for investors and other company stakeholders through compliance with those principles.', 'The purpose of this Code is to establish best-practice corporate governance principles in Bahrain, and to provide protection for investors and other company stakeholders through compliance with those principles.', 'The purpose of this Code is to establish best-practice corporate governance principles in Bahrain, and to provide protection for investors and other company stakeholders through compliance with those principles.', 'Bahrain', 'governance', 'in_force', '2010-01-01'::date, 'Bahrain', 'https://www.carrotsandsticks.org/policies/12_3', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg9', 'bahrain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c0f65c7-d7cf-5bc5-bb87-62c372fbd26f', 'Bangladesh DSE Sustainability Reporting Guide Version 03', 'DSE Sustainability Reporting Guide Version 03 2023', 'This Guide updates sustainability reporting standards in response to evolving guidelines, such as the GRI Universal Standards 2021. Reflecting two decades of progress, it aligns with global directives like the UN SDGs and EU regulations, influencing corporate reporting on triple bottom line impacts and stock exchange disclosures.', 'This Guide updates sustainability reporting standards in response to evolving guidelines, such as the GRI Universal Standards 2021. Reflecting two decades of progress, it aligns with global directives like the UN SDGs and EU regulations, influencing corporate reporting on triple bottom line impacts and stock exchange disclosures.', 'This Guide updates sustainability reporting standards in response to evolving guidelines, such as the GRI Universal Standards 2021. Reflecting two decades of progress, it aligns with global directives like the UN SDGs and EU regulations, influencing corporate reporting on triple bottom line impacts and stock exchange disclosures.', 'Bangladesh', 'climate', 'in_force', '2023-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_18', ARRAY['sdg13', 'bangladesh', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3e31afa0-7d41-513f-9813-189624203d6d', 'Bangladesh Green Bond Financing for Banks and Financial Institutions', 'Policy on Green Bond Financing for Banks and Financial Institutions (Fis), 2022', 'The objective of the Policy on Green Bond Financing for Banks and FIs is to facilitate sustainable investment by banks and financial institutions with a focus on climate change mitigation and adaptation, energy and resource efficiency, and a green economy.', 'The objective of the Policy on Green Bond Financing for Banks and FIs is to facilitate sustainable investment by banks and financial institutions with a focus on climate change mitigation and adaptation, energy and resource efficiency, and a green economy.', 'The objective of the Policy on Green Bond Financing for Banks and FIs is to facilitate sustainable investment by banks and financial institutions with a focus on climate change mitigation and adaptation, energy and resource efficiency, and a green economy.', 'Bangladesh', 'climate', 'in_force', '2022-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_17', ARRAY['sdg2', 'sdg13', 'bangladesh', 'sdg7', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('932cd769-5a6b-5530-a56a-7ad0576e1a06', 'Bangladesh Sustainable Finance Policy for Banks and Financial Institutions', 'Sustainable Finance Policy for Banks and Financial Institutions', 'In 2020, Bangladesh introduced a Sustainable Finance Policy for Banks and Financial Institutions aimed at promoting sustainable development in the country. The policy requires banks and financial institutions to integrate environmental, social, and governance (ESG) factors into their lending, investment, and risk management practices. Under the policy, banks and financial institutions are required to establish a sustainable finance unit and a board-level sustainability committee to oversee their sustainable finance activities. They are also required to report on their sustainable finance activities in their annual reports and disclose information on their ESG risks and opportunities. The policy sets out specific targets for banks and financial institutions to achieve, including increasing the percentage of their lending to sustainable sectors, such as renewable energy, and reducing their exposure to high-risk sectors, such as coal mining. Overall, the Sustainable Finance Policy for Banks and Financial Institutions 2020 Bangladesh is a significant step towards promoting sustainable development in the country and aligning the financial sector with national and global sustainability goals.', 'In 2020, Bangladesh introduced a Sustainable Finance Policy for Banks and Financial Institutions aimed at promoting sustainable development in the country. The policy requires banks and financial institutions to integrate environmental, social, and governance (ESG) factors into their lending, investment, and risk management practices. Under the policy, banks and financial institutions are required to establish a sustainable finance unit and a board-level sustainability committee to oversee their sustainable finance activities. They are also required to report on their sustainable finance activities in their annual reports and disclose information on their ESG risks and opportunities. The policy sets out specific targets for banks and financial institutions to achieve, including increasing the percentage of their lending to sustainable sectors, such as renewable energy, and reducing their exposure to high-risk sectors, such as coal mining. Overall, the Sustainable Finance Policy for Banks and Financial Institutions 2020 Bangladesh is a significant step towards promoting sustainable development in the country and aligning the financial sector with national and global sustainability goals.', 'In 2020, Bangladesh introduced a Sustainable Finance Policy for Banks and Financial Institutions aimed at promoting sustainable development in the country. The policy requires banks and financial institutions to integrate environmental, social, and governance (ESG) factors into their lending, investment, and risk management practices. Under the policy, banks and financial institutions are required to establish a sustainable finance unit and a board-level sustainability committee to oversee their sustainable finance activities. They are also required to report on their sustainable finance activities in their annual reports and disclose information on their ESG risks and opportunities. The policy sets out specific targets for banks and financial institutions to achieve, including increasing the percentage of their lending to sustainable sectors, such as renewable energy, and reducing their exposure to high-risk sectors, such as coal mining. Overall, the Sustainable Finance Policy for Banks and Financial Institutions 2020 Bangladesh is a significant step towards promoting sustainable development in the country and aligning the financial sector with national and global sustainability goals.', 'Bangladesh', 'climate', 'in_force', '2020-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_16', ARRAY['sdg2', 'bangladesh', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('48aec644-2840-5909-82b2-8ec931b011ca', 'Sustainability Reporting for Listed Companies in Bangladesh', 'Guidance on Sustainability Reporting for Listed Companies in Bangladesh', '"Guidance on Sustainability Reporting for Listed Companies in Bangladesh" aims to promote sustainable practices and reporting among companies listed on the stock exchange. The guidance outlines key principles, disclosures, and reporting formats for sustainability reporting, including environmental, social, and governance (ESG) issues. It encourages companies to report on their sustainability performance, risks, and opportunities, and to engage with stakeholders on sustainability matters. The guidance also provides guidance on how companies can integrate sustainability into their corporate governance structures and strategies. There is an expectation that listed companies will adopt the guidance and publish their sustainability reports annually.', '"Guidance on Sustainability Reporting for Listed Companies in Bangladesh" aims to promote sustainable practices and reporting among companies listed on the stock exchange. The guidance outlines key principles, disclosures, and reporting formats for sustainability reporting, including environmental, social, and governance (ESG) issues. It encourages companies to report on their sustainability performance, risks, and opportunities, and to engage with stakeholders on sustainability matters. The guidance also provides guidance on how companies can integrate sustainability into their corporate governance structures and strategies. There is an expectation that listed companies will adopt the guidance and publish their sustainability reports annually.', '"Guidance on Sustainability Reporting for Listed Companies in Bangladesh" aims to promote sustainable practices and reporting among companies listed on the stock exchange. The guidance outlines key principles, disclosures, and reporting formats for sustainability reporting, including environmental, social, and governance (ESG) issues. It encourages companies to report on their sustainability performance, risks, and opportunities, and to engage with stakeholders on sustainability matters. The guidance also provides guidance on how companies can integrate sustainability into their corporate governance structures and strategies. There is an expectation that listed companies will adopt the guidance and publish their sustainability reports annually.', 'Bangladesh', 'climate', 'in_force', '2019-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_11', ARRAY['guidance_frameworks', 'bangladesh', 'sdg7', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca6e34cf-6107-5b1e-8132-4ef90fee3bcf', 'Accord on Fire and Building Safety in Bangladesh: May', 'Accord on Fire and Building Safety in Bangladesh: May 2018', 'The signatories to this Agreement agree to continue a fire and building safety program in Bangladesh until midnight of May 31, 2021, when this agreement will expire. At the end of that time, the work will be handed over to a national regulatory body, supported by the International Labor Organization, to be carried forward from that point.', 'The signatories to this Agreement agree to continue a fire and building safety program in Bangladesh until midnight of May 31, 2021, when this agreement will expire. At the end of that time, the work will be handed over to a national regulatory body, supported by the International Labor Organization, to be carried forward from that point.', 'The signatories to this Agreement agree to continue a fire and building safety program in Bangladesh until midnight of May 31, 2021, when this agreement will expire. At the end of that time, the work will be handed over to a national regulatory body, supported by the International Labor Organization, to be carried forward from that point.', 'Bangladesh', 'climate', 'in_force', '2018-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_12', ARRAY['bangladesh', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c9f2ff47-166d-51f6-8ef5-76eda05b84e7', 'Bangladesh Corporate Governance Code', 'Corporate Governance Code, 2018', 'The codes require a company to separately spell out detailed roles, responsibilities and codes of conduct for its chairman, all directors, Managing Director (MD)/Chief Executive Officer (CEO), Company Secretary (CS), Chief Financial Officer (CFO), Head of Internal Audit & Compliance (HIAC), Audit Committee (AC) and Nomination and Remuneration Committee (NRC). All these are to be posted in detail on the company website.', 'The codes require a company to separately spell out detailed roles, responsibilities and codes of conduct for its chairman, all directors, Managing Director (MD)/Chief Executive Officer (CEO), Company Secretary (CS), Chief Financial Officer (CFO), Head of Internal Audit & Compliance (HIAC), Audit Committee (AC) and Nomination and Remuneration Committee (NRC). All these are to be posted in detail on the company website.', 'The codes require a company to separately spell out detailed roles, responsibilities and codes of conduct for its chairman, all directors, Managing Director (MD)/Chief Executive Officer (CEO), Company Secretary (CS), Chief Financial Officer (CFO), Head of Internal Audit & Compliance (HIAC), Audit Committee (AC) and Nomination and Remuneration Committee (NRC). All these are to be posted in detail on the company website.', 'Bangladesh', 'governance', 'in_force', '2018-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_3', ARRAY['bangladesh', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('676e3f89-cf64-5544-842d-799956030636', 'Bangladesh Environmental & Social Risk Management (ESRM) for Banks', 'Guidelines on Environmental & Social Risk Management (ESRM) for Banks and Financial Institutions in Bangladesh', 'This update to ERM Guidelines has been developed to address the recommendations of the ERM Guidelines and the outcomes of ESRM baseline survey for the financial sector through a long process of in-house study and research within BB, having technical support from IFC (International Finance Corporation), three tier consultation (Mail/E-mail based consultation, web-based consultation and live consultation) with banks and FIs, consultation with development partners working on E&S issues in financial sector.', 'This update to ERM Guidelines has been developed to address the recommendations of the ERM Guidelines and the outcomes of ESRM baseline survey for the financial sector through a long process of in-house study and research within BB, having technical support from IFC (International Finance Corporation), three tier consultation (Mail/E-mail based consultation, web-based consultation and live consultation) with banks and FIs, consultation with development partners working on E&S issues in financial sector.', 'This update to ERM Guidelines has been developed to address the recommendations of the ERM Guidelines and the outcomes of ESRM baseline survey for the financial sector through a long process of in-house study and research within BB, having technical support from IFC (International Finance Corporation), three tier consultation (Mail/E-mail based consultation, web-based consultation and live consultation) with banks and FIs, consultation with development partners working on E&S issues in financial sector.', 'Bangladesh', 'climate', 'in_force', '2017-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_6', ARRAY['guidance_frameworks', 'sdg14', 'other sustainability policy', 'bangladesh', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bdd5ed43-3725-5474-b204-1cc36d46cf67', 'Bangladesh Chittagong Stock Exchange (Listing) Regulations', 'Chittagong Stock Exchange (Listing) Regulations, 2015', 'The Chittagong Stock Exchange (Listing) Regulations, 2015 in Bangladesh is a set of regulations that govern the listing and trading of securities on the Chittagong Stock Exchange. The regulations place obligations on businesses seeking to list their securities on the exchange, including the obligation to provide accurate and timely financial information, maintain a minimum level of public float, and comply with various disclosure requirements. The regulations also establish rules and procedures for the delisting of securities from the exchange. Businesses are required to comply with the regulations and ensure that their securities remain in compliance with the requirements for continued listing on the exchange. Non-compliance with the regulations can result in penalties, including the potential delisting of securities from the exchange.', 'The Chittagong Stock Exchange (Listing) Regulations, 2015 in Bangladesh is a set of regulations that govern the listing and trading of securities on the Chittagong Stock Exchange. The regulations place obligations on businesses seeking to list their securities on the exchange, including the obligation to provide accurate and timely financial information, maintain a minimum level of public float, and comply with various disclosure requirements. The regulations also establish rules and procedures for the delisting of securities from the exchange. Businesses are required to comply with the regulations and ensure that their securities remain in compliance with the requirements for continued listing on the exchange. Non-compliance with the regulations can result in penalties, including the potential delisting of securities from the exchange.', 'The Chittagong Stock Exchange (Listing) Regulations, 2015 in Bangladesh is a set of regulations that govern the listing and trading of securities on the Chittagong Stock Exchange. The regulations place obligations on businesses seeking to list their securities on the exchange, including the obligation to provide accurate and timely financial information, maintain a minimum level of public float, and comply with various disclosure requirements. The regulations also establish rules and procedures for the delisting of securities from the exchange. Businesses are required to comply with the regulations and ensure that their securities remain in compliance with the requirements for continued listing on the exchange. Non-compliance with the regulations can result in penalties, including the potential delisting of securities from the exchange.', 'Bangladesh', 'governance', 'in_force', '2015-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_14', ARRAY['mandatory', 'bangladesh', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0d225c24-09bc-5e76-a79c-439b11c4dc84', 'Bangladesh Revised Green Banking Policy for National Bank Limited', 'Revised Green Banking Policy for National Bank Limited', 'In response to the global initiatives of Green Banking, Bangladesh Bank has instructed banks in Bangladesh to implement green initiatives through B R P D Circular 02 dated February 27, 2011 and advised all banks in the country to lay down the foundation of green banking. In accordance with the Bangladesh Bank’s guideline, Green Banking Policy for National Bank Limited has prepared which was duly approved by the Board of Directors in its 332nd meeting held on 19.09.2012. It requires more time to implement Green Banking Policy of the bank. Bangladesh Bank, realizing the fact, informed banks vide their GBCSRD Circular No. 08 that the deadline for implementation of Phase II and Phase III has been extended. Accordingly, National Bank Limited prepared revised policy for Green Banking. This Policy is to be read in conjunction with the Environmental Risk Management guidelines of the Bangladesh Bank, duly amended from time to time and all circulars/directives issued by the Bank from time to time.', 'In response to the global initiatives of Green Banking, Bangladesh Bank has instructed banks in Bangladesh to implement green initiatives through B R P D Circular 02 dated February 27, 2011 and advised all banks in the country to lay down the foundation of green banking. In accordance with the Bangladesh Bank’s guideline, Green Banking Policy for National Bank Limited has prepared which was duly approved by the Board of Directors in its 332nd meeting held on 19.09.2012. It requires more time to implement Green Banking Policy of the bank. Bangladesh Bank, realizing the fact, informed banks vide their GBCSRD Circular No. 08 that the deadline for implementation of Phase II and Phase III has been extended. Accordingly, National Bank Limited prepared revised policy for Green Banking. This Policy is to be read in conjunction with the Environmental Risk Management guidelines of the Bangladesh Bank, duly amended from time to time and all circulars/directives issued by the Bank from time to time.', 'In response to the global initiatives of Green Banking, Bangladesh Bank has instructed banks in Bangladesh to implement green initiatives through B R P D Circular 02 dated February 27, 2011 and advised all banks in the country to lay down the foundation of green banking. In accordance with the Bangladesh Bank’s guideline, Green Banking Policy for National Bank Limited has prepared which was duly approved by the Board of Directors in its 332nd meeting held on 19.09.2012. It requires more time to implement Green Banking Policy of the bank. Bangladesh Bank, realizing the fact, informed banks vide their GBCSRD Circular No. 08 that the deadline for implementation of Phase II and Phase III has been extended. Accordingly, National Bank Limited prepared revised policy for Green Banking. This Policy is to be read in conjunction with the Environmental Risk Management guidelines of the Bangladesh Bank, duly amended from time to time and all circulars/directives issued by the Bank from time to time.', 'Bangladesh', 'governance', 'in_force', '2014-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_7', ARRAY['mandatory', 'bangladesh', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('88e5eed8-807f-594c-bbc4-fb4c826f4a87', 'Accord on Fire and Building Safety in Bangladesh', 'Accord on Fire and Building Safety in Bangladesh, 2013', 'The programme will build on the National Action Plan on Fire Safety (NAP), which expressly welcomes the development and implementation by any stakeholder of any other activities that would constitute a meaningful contribution to improving fire safety in Bangladesh. The signatories commit to align this programme and its activities with the NAP and to ensure a close collaboration, including for example by establishing common programme, liaison and advisory structures.', 'The programme will build on the National Action Plan on Fire Safety (NAP), which expressly welcomes the development and implementation by any stakeholder of any other activities that would constitute a meaningful contribution to improving fire safety in Bangladesh. The signatories commit to align this programme and its activities with the NAP and to ensure a close collaboration, including for example by establishing common programme, liaison and advisory structures.', 'The programme will build on the National Action Plan on Fire Safety (NAP), which expressly welcomes the development and implementation by any stakeholder of any other activities that would constitute a meaningful contribution to improving fire safety in Bangladesh. The signatories commit to align this programme and its activities with the NAP and to ensure a close collaboration, including for example by establishing common programme, liaison and advisory structures.', 'Bangladesh', 'governance', 'in_force', '2013-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_13', ARRAY['bangladesh', 'other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('557bb452-210d-597b-a359-4b0902d9c194', 'Bangladesh Securities and Exchange Commission (SEC) - Corporate', 'Bangladesh Securities and Exchange Commission (SEC) - Corporate Governance Guidelines', 'The Corporate Governance Code establishes rules for companies listed on the Bangladesh stock exchanges to ensure transparency, accountability, and the protection of shareholders. It includes guidelines on the structure of the Board of Directors, the appointment of independent directors, and the disclosure of financial information. Key provisions include:
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('97195b11-6f1c-5d23-80cd-c69c7e454f45', 'Bangladesh Codes of Conduct For Selected Segments of the', 'Codes of Conduct For Selected Segments of the Shrimp Aquaculture Industry in Bangladesh', 'The principal objectives of this document is to prepare a set of code of conduct for various segments of the shrimp aquaculture industry in Bangladesh to help ensure: (i) Food safety by minimizing biological and chemical risks and hazards that are likely to affect human health, (ii) Traceability of the food,(iii) Environmental sustainability and bio-diversity,(iv) Labour standard and, (v) Social harmony at each step of the value chain.', 'The principal objectives of this document is to prepare a set of code of conduct for various segments of the shrimp aquaculture industry in Bangladesh to help ensure: (i) Food safety by minimizing biological and chemical risks and hazards that are likely to affect human health, (ii) Traceability of the food,(iii) Environmental sustainability and bio-diversity,(iv) Labour standard and, (v) Social harmony at each step of the value chain.', 'The principal objectives of this document is to prepare a set of code of conduct for various segments of the shrimp aquaculture industry in Bangladesh to help ensure: (i) Food safety by minimizing biological and chemical risks and hazards that are likely to affect human health, (ii) Traceability of the food,(iii) Environmental sustainability and bio-diversity,(iv) Labour standard and, (v) Social harmony at each step of the value chain.', 'Bangladesh', 'nature', 'in_force', '2011-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_15', ARRAY['sdg8', 'sdg14', 'bangladesh', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8bc436af-4042-5e0b-b4b2-c9c7ae49c2c9', 'Bangladesh Bank - Green Banking Policy and Guidelines', 'Bangladesh Bank - Green Banking Policy and Guidelines', 'The Sustainable Finance Policy by Bangladesh Bank outlines guidelines for integrating Environmental, Social, and Governance (ESG) considerations into the financial services sector. The policy encourages financial institutions, such as banks and financial companies, to support the transition to a green economy by financing projects that contribute to sustainability and climate resilience. It covers both Green Finance and Sustainable Finance, establishing criteria for green products and projects, including those related to renewable energy, energy efficiency, sustainable agriculture, and socially responsible financing.', 'The Sustainable Finance Policy by Bangladesh Bank outlines guidelines for integrating Environmental, Social, and Governance (ESG) considerations into the financial services sector. The policy encourages financial institutions, such as banks and financial companies, to support the transition to a green economy by financing projects that contribute to sustainability and climate resilience. It covers both Green Finance and Sustainable Finance, establishing criteria for green products and projects, including those related to renewable energy, energy efficiency, sustainable agriculture, and socially responsible financing.', 'The Sustainable Finance Policy by Bangladesh Bank outlines guidelines for integrating Environmental, Social, and Governance (ESG) considerations into the financial services sector. The policy encourages financial institutions, such as banks and financial companies, to support the transition to a green economy by financing projects that contribute to sustainability and climate resilience. It covers both Green Finance and Sustainable Finance, establishing criteria for green products and projects, including those related to renewable energy, energy efficiency, sustainable agriculture, and socially responsible financing.', 'Bangladesh', 'climate', 'in_force', '2011-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_2', ARRAY['guidance_frameworks', 'sdg13', 'bangladesh', 'sdg2', 'sdg7', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d1b1ec02-2ba5-5863-8a6e-eab2b9f6d8a9', 'Bangladesh Code of Corporate Governance for Bangaldesh', 'The Code of Corporate Governance for Bangaldesh', 'This Code of Corporate Governance, prescribes the principles, procedures and process through which better corporate governance practices may gradually be introduced. As such, the Code is organised into Principles and Guidelines.', 'This Code of Corporate Governance, prescribes the principles, procedures and process through which better corporate governance practices may gradually be introduced. As such, the Code is organised into Principles and Guidelines.', 'This Code of Corporate Governance, prescribes the principles, procedures and process through which better corporate governance practices may gradually be introduced. As such, the Code is organised into Principles and Guidelines.', 'Bangladesh', 'governance', 'in_force', '2004-01-01'::date, 'Bangladesh', 'https://www.carrotsandsticks.org/policies/13_8', ARRAY['bangladesh', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
